from build_ra2 import *

def pillx(cls, text, spin=False):
    mark = '<span class="spin" aria-hidden="true"></span>' if spin else '<span class="dot"></span>'
    return '<span class="pill %s">%s%s</span>' % (cls, mark, text)

def grid(cells, cols=4):
    return '<div class="app" style="padding: 32px; box-sizing: border-box;"><div style="display: grid; grid-template-columns: repeat(%d, minmax(0,1fr)); gap: 24px 20px; align-items: start;">%s</div></div>' % (cols, "\n".join(cells))

TIP = '<div style="position: relative; display: inline-block; margin-top: 46px;"><div class="seg" style="width: 180px;"><button type="button" class="on">Lively</button><button type="button">Calm</button></div><div style="position: absolute; left: 0; top: -44px; background: #1C1917; color: #F5F2EE; font-size: 12.5px; line-height: 17px; padding: 6px 10px; border-radius: 8px; width: 260px;">Moves on almost every line, and reacts while the others talk.</div></div>'

# ---------------------------------------------------------------- more Group states
idle_stage = stage("Not running", "#6B635A", "Not running", "", "0:00 / 6:00", 0,
    mb("Group talk", "robots + people", "grp") + mb("Interrupt", "they cut you off", "int") + mb("Free talk", "chat about anything", "free")
    + btn("Get ready", "primary", extra=' style="min-height: 52px;" title="Connects the robots, checks every service and makes the first lines ahead"')
    + btn("Disconnect", "ghost", "unlink", disabled=True, extra=' style="min-height: 52px;"'),
    '<span class="okline">%sMic: DJI mic plugged in (used when the robots connect)</span><span class="muted">3 Reachys at the table.</span>' % ic("mic", 16))
free_seat = seat(0, "Max", "reachy1", "Available", "ElevenLabs", "Daniel", ELV, WRITERS[0], 3, "Lively", 150, "For AI music: optimistic, brings examples of tools musicians already use.", meter=0, locked=False)
free_seat = free_seat.replace('aria-label="Add a laptop robot here"', 'aria-label="Add a laptop robot here" title="Add a robot here (it talks through this laptop\'s speaker)"').replace('aria-label="Take off the table"', 'aria-label="Take off the table" title="Take this Reachy off the table (tick Included to bring it back)"')
excl = seat(1, "Leo", "reachy3", "Available", "OpenAI", "onyx (male, deep)", OAV, WRITERS[1], 4, "Calm", 130, "Against: skeptical.", meter=0, out=True, inc=False, vline="Voice: OpenAI, writing via OpenRouter").replace('aria-label="Take off the table"', 'aria-label="Take off the table" disabled="{{yes}}"')

def phase_tile(phase, col, big, det, extra=""):
    return '<div class="pnl" style="gap: 4px;"><div class="phase" style="color: %s;"><span class="pdot"></span>%s</div><p class="big" style="font-size: 17px; line-height: 23px;">%s</p><p class="det" style="font-size: 13px;">%s</p>%s</div>' % (col, phase, big, det, extra)

cells_t = [
 cell("Group before connecting", idle_stage, span=4),
 cell("Seats can be edited before connecting", '<div style="display: flex; flex-direction: column; gap: 12px;"><div style="display: grid; grid-template-columns: 1fr 1fr; gap: 12px;">%s%s</div><p class="sub">Leo is off the table: dimmed, the seat controls stay at full strength, × is off.</p></div>' % (free_seat, excl), span=3),
 cell("Get ready", '<div class="pnl" style="gap: 8px;">%s%s%s<p class="sub">Disabled with fewer than 2 included robots, while running, or while the hub warms up (it says which).</p></div>' % (
     btn("Get ready", "primary", extra=' style="min-height: 44px;"'), '<button class="btn btn-quiet busy" type="button" disabled="{{yes}}" style="min-height: 44px;">Getting ready…</button>',
     '<button class="btn" type="button" style="min-height: 44px; background: #ECFDF3; color: #15803D; box-shadow: inset 0 0 0 1px #86D9A4;">%sReady · 8 checks ok</button>' % ic("check", 18))),
 cell("Phases", '<div style="display: grid; grid-template-columns: repeat(3, minmax(0,1fr)); gap: 10px;">%s</div>' % "".join([
     phase_tile("Starting", "#A84E00", "Starting…", "connecting to the robots · loading voice detection · stopping the robots' own apps", '<div style="display: flex; gap: 6px; margin-top: 6px;">%s%s</div>' % (mb("Group talk", "connecting…", "grp"), btn("Stop", "stop", extra=' style="min-height: 40px;"'))),
     phase_tile("Listening", "#15803D", "Listening to the room", "Group talk · waiting for the rest"),
     phase_tile("Listening", "#15803D", "Waiting for you to talk", "Interrupt"),
     phase_tile("Thinking", "#A84E00", "Thinking…", "Group talk · answering the person"),
     phase_tile("People speaking", "#B45309", "The people are speaking", "Group talk"),
     phase_tile("Stopping", "#8A3B00", "Stopping…", "disconnecting the robots", '<div style="display: flex; gap: 6px; margin-top: 6px;"><button class="btn btn-stop" type="button" disabled="{{yes}}" style="min-height: 40px;">Stopping…</button></div>'),
 ]), span=3),
 cell("Robot states on a card", '<div class="pnl" style="gap: 8px;"><div style="display: flex; gap: 6px; flex-wrap: wrap;">%s</div><p class="note2" style="padding-left: 0;">3:40 reachy6 dropped out: no answer. The rest carry on.</p><p class="note2" style="padding-left: 0;">reachy5 is not connected; it sits this one out</p></div>' % "".join([
     pillx("p-off", "Absent"), pillx("p-near", "Available"), pillx("p-busy", "Connecting", True), pillx("p-conn", "Connected"), pillx("p-run", "Running"), pillx("p-warn", "Degraded"), pillx("p-lost", "Lost"), pillx("p-off", "Unavailable"), pillx("p-off", "Not connected")])),
 cell("Choir on", '<div class="pnl" style="gap: 8px;"><div class="pnlh"><span class="sub" title="Groups. Used from the next Start.">All robots as one voice</span><span class="spacer"></span><button class="btn btn-sm" type="button" aria-pressed="true" style="min-height: 32px; font-size: 13px; background: #EEF4FF; color: #1D4ED8;">%sChoir: on</button></div><p class="sub">Robots you tick later join too. Used from the next Start.</p></div>' % ic("users", 14)),
 cell("Voice list marks", '<div class="pnl" style="gap: 8px;">%s%s%s</div>' % (sel(["ElevenLabs (no key)", "Auto", "OpenAI"], aria="Voice service"), sel(["Default (no ElevenLabs key)"], aria="Voice"), sel(["x8Kq3 (not in the list)", "Default (Daniel)", "Daniel"], aria="Voice") + sel(["shimmer (not here: uses Default)", "Default (ash)", "ash (male)"], aria="Voice"))),
 cell("Saving", '<div class="pnl" style="gap: 6px;"><div style="display: flex; gap: 6px; flex-wrap: wrap;"><span class="chk">loading</span><span class="chk">saving</span><span class="chk" style="color: #8A3B00; background: #FFF1D6;">not saved yet</span><span class="chk bad">not saved</span><span class="chk ok">saved</span></div><span class="sub">Saving shortly…</span><span class="sub">Saving…</span><span class="sub" style="color: #B91C1C;">Not saved: someone else changed it. The hub\'s version is back.</span>%s</div>' % n("err", "alert", "The setup couldn't be saved, so the conversation didn't start.")),
 cell("Link to the hub", '<div class="pnl" style="gap: 8px;"><div style="display: flex; gap: 12px; flex-wrap: wrap;"><span class="live"><span class="ldot"></span>Live</span><span class="live" style="color: #A84E00;"><span class="spin" style="width: 10px; height: 10px;"></span>Connecting</span><span class="live" style="color: #8A3B00;"><span class="spin" style="width: 10px; height: 10px;"></span>Reconnecting</span></div>%s%s</div>' % (n("err", "alert", "The hub didn't answer (timeout). The screen may be out of date."), n("err", "alert", "This Robot Hub has no Group yet. Restart Robot Hub."))),
 cell("Every start refusal", '<div class="pnl" style="gap: 4px;">%s</div>' % "".join('<p class="sub" style="color: #B91C1C;">Couldn\'t start: %s</p>' % t for t in [
     "no seats are included.", "two robots are called Leo. Give each its own name.", "the hub needs an OpenRouter, OpenAI or Gemini key (Settings, Keys).",
     "stop the conversation to switch simulation.", "stop the conversation to add or remove robots.", "couldn't connect the robots: reachy6 timed out. Everything is disconnected again.", "unknown mode \"debate\"."]), span=2),
 cell("Transcript rows", '<div class="pnl" style="gap: 2px;">%s%s%s%s%s%s<p class="note2">6:01 Leo\'s closing line failed: voice timeout</p></div>' % (
     line(0, "Max", "reachy1", "", "", "1:12", '<span class="muted">…</span>'),
     '<div class="ln2 people now" style="--sc: #D97706;"><span class="cb"></span><div><div class="lh"><span class="who">People</span><span>1:15</span></div><div class="tx"><i class="muted">listening…</i></div></div></div>',
     '<div class="ln2 people" style="--sc: #D97706;"><span class="cb"></span><div><div class="lh"><span class="who">People</span><span>1:31</span></div><div class="tx"><i class="muted">(said something the robots couldn\'t make out)</i></div></div></div>',
     '<div class="ln2" style="--sc: #2563EB;"><span class="cb"></span><div><div class="lh"><span class="who">Group 1</span><span class="rtag">Max\'s voice</span><span class="mtag">build</span><span>760 ms</span><span>2:02</span></div><div class="tx">We agree on one thing: the song still needs a person.</div></div></div>',
     line(0, "Max", "reachy1", "wrap", 690, "6:00", "Thanks for listening. Make something only you could make."),
     line(2, "Reachy Mini 3", "reachy6", "wrap", 720, "6:04", "And check the numbers before you believe a robot. Bye!")), span=2),
 cell("Simulate on", '<div class="pnl" style="gap: 8px;"><span class="sub">Simulation: this laptop speaks and listens.</span><div class="seat" style="--sc: #2563EB;"><div class="seathd"><span class="sn">1</span><input class="lab" type="text" value="Reachy Mini 1" aria-label="Label"></div><span class="rtag" style="align-self: flex-start;">laptop speaker</span><p class="sub">No + or ×. A mode needs only one seat.</p></div>%s</div>' % mb("Group talk", "robots + people", "grp")),
 cell("Five robots", '<div class="pnl" style="gap: 8px;"><div style="display: grid; grid-template-columns: repeat(5, minmax(0,1fr)); gap: 6px;">%s</div><p class="sub">From 4 robots the cards get tighter and hide the voice line. From 6, two rows and the page scrolls.</p></div>' % "".join(
     '<div class="seat" style="--sc: %s; padding: 8px; gap: 6px;"><div class="seathd"><span class="sn" style="width: 20px; height: 20px; font-size: 11px;">%d</span><b style="font-size: 12px;">%s</b></div><span class="meter" style="flex: none;"><span style="width: %d%%;"></span></span></div>' % (SEAT[k], k + 1, nm, m)
     for k, (nm, m) in enumerate([("Max", 30), ("Leo", 70), ("Mia", 0), ("Ori", 10), ("Noa", 5)])), span=2),
 cell("Audience mic", '<div class="pnl" style="gap: 8px;">%s%s<p class="sub">While running: use the mic switch on the stage.</p><p class="sub">Hearing the audience through the DJI mic.</p></div>' % (
     sel(["Auto (DJI mic when plugged in)", "Auto (DJI mic, plugged in)", "Robots' own mics", "Laptop's built-in mic", "Old USB mic (not plugged in)"], "Old USB mic (not plugged in)", aria="Audience mic"),
     sel(["Auto (DJI mic, plugged in)"], aria="Audience mic", style="opacity: .5;"))),
 cell("Limits and tooltips", '<div class="pnl" style="gap: 8px;"><div style="display: flex; gap: 6px; align-items: center;"><button class="ib" type="button" disabled="{{yes}}" title="No more robots fit">%s</button><span class="sub">5 laptop robots: No more robots fit</span></div>%s</div>' % (ic("plus", 16), TIP)),
 cell("Groups dialog, empty", '<div class="pnl" style="gap: 8px;"><p class="muted" style="margin: 0;">No groups: every robot is on its own.</p><label class="check" style="opacity: .5;" title="Not included in the conversation: it sits this one out."><input type="checkbox" disabled>Leo <span class="muted" style="font-size: 13px;">reachy3 · not included</span></label>%s</div>' % btn("Add group", "quiet", "plus", extra=SM)),
 cell("Ended", '<div class="pnl" style="gap: 6px;"><p class="note2" style="padding-left: 0;">6:05 the conversation is over</p><p class="sub">The lines stay until the next connection: Stop and a mode switch keep them.</p></div>'),
 cell("More toasts", '<div style="display: flex; flex-wrap: wrap; gap: 8px; align-items: flex-start;">%s</div>' % "".join('<div class="toast" style="position: static; transform: none;%s">%s</div>' % (' background: #7F1D1D;' if bad else "", t) for t, bad in [
     ("Choir off: every robot is on its own (from the next Start).", 0), ("Choir needs at least two included robots.", 1), ("Pick at least one robot and one setting.", 1),
     ("Not sent: the hub didn't answer.", 1), ("Couldn't switch the mic: connect the robots first.", 1), ("Couldn't stop: the hub didn't answer.", 1),
     ("Couldn't disconnect: the hub didn't answer.", 1), ("Couldn't get ready: couldn't connect the robots.", 1)]), span=4),
]
write("RAMoreTable.dc.html", page("reachy_app: more Group states", grid(cells_t), "renderVals() { return { yes: true }; }", width=1600, height=2860, extra_css=RA_CSS, mono=True))

# ---------------------------------------------------------------- more Talk and Wizard of Oz states
def robot_state(pill, sub, buttons, extra=""):
    return '<div class="pnl" style="gap: 8px;"><div class="srow">%s<span class="sub" style="margin-left: auto;">%s</span></div>%s<div style="display: flex; gap: 8px;">%s</div></div>' % (pill, sub, extra, buttons)

GPTV = ["Default (gleam)", "gleam", "meridian", "quartz", "ripple", "vesper", "willow", "stone", "beacon", "delta", "cinder", "bossa", "tempo"]
SMB = ' style="min-height: 36px; font-size: 14px; flex: 1 1 0;"'
cells_k = [
 cell("System: loading", robot_state(pillx("p-near", "Connecting…", True), "", btn("Stop system", "quiet", "stop", disabled=True, extra=SMB) + btn("Start system", "quiet", "play", disabled=True, extra=SMB))),
 cell("System: starting", robot_state(pillx("p-busy", "Starting…", True), "7-10 s", btn("Stop system", "quiet", "stop", disabled=True, extra=SMB) + btn("Start system", "quiet", "play", disabled=True, extra=SMB))),
 cell("System: ready", robot_state(pillx("p-run", "Idle"), "Daemon active", btn("Stop system", "quiet", "stop", extra=SMB) + btn("Start system", "quiet", "play", disabled=True, extra=SMB), btn("Start conversation", "primary", "play", extra=' style="min-height: 44px;"'))),
 cell("System: shutting down, error", '<div style="display: flex; flex-direction: column; gap: 10px;">%s%s</div>' % (
     robot_state(pillx("p-warn", "Shutting down", True), "", ""), robot_state(pillx("p-lost", "Error"), "", "", n("err", "alert", "Couldn't stop the system: it isn't running.")))),
 cell("Key missing, before Start", '<div class="pnl" style="gap: 8px;"><div style="display: flex; gap: 8px; align-items: center;"><span class="badge">OpenAI GPT-Live-1</span><span class="badge" style="background: #FEF2F2; color: #B91C1C;" title="No OpenAI key yet">No key</span></div><div class="frow"><label>Brain</label>%s</div><p class="sub" style="color: #B91C1C;">No OpenAI key yet. Add one in Settings.</p><p class="sub" style="color: #B91C1C;">ElevenLabs: the key was refused.</p></div>' % sel(["OpenAI GPT-Live-1 (no key)"], aria="Brain")),
 cell("GPT-Live voices and vision", '<div class="pnl" style="gap: 8px;"><span class="badge">GPT-Live-1 + ElevenLabs voice</span><div class="frow"><label>Brain voice</label>%s<label>Character voice</label>%s</div><p class="sub">%sRobot camera · described for the model by gpt-4.1-mini</p><p class="sub">Test image: lab-table.jpg</p><p class="sub" style="color: #8A3B00;">Test image not found: lab-table.jpg</p></div>' % (sel(GPTV, GPTV[0], aria="Brain voice"), sel(["Default voice (gleam)"] + GPTV[1:], aria="Character voice"), ic("camera", 14))),
 cell("ElevenLabs voices failed", '<div class="pnl" style="gap: 8px;"><div class="frow"><label>EL voice</label>%s</div><p class="sub" style="color: #B91C1C;">Couldn\'t load the ElevenLabs voices.</p><p class="sub" style="color: #B91C1C;">Couldn\'t change that: "fr" is not a language here.</p></div>' % sel(["No voices (check the key)"], aria="ElevenLabs voice")),
 cell("Start refusals as sentences", '<div class="pnl" style="gap: 6px;">%s%s%s</div>' % (n("err", "alert", "Already talking. End this conversation first."), n("warn", "clock", "Still starting. Try again in a few seconds."), n("err", "alert", "ElevenLabs voice is on, but no voice is chosen and the account's list couldn't be read."))),
 cell("Ending", '<div class="pnl" style="gap: 8px;"><button class="btn btn-stop busy" type="button" disabled="{{yes}}" style="min-height: 44px;">Ending… the robot finishes its line</button><p class="sub">Up to 40 s.</p></div>'),
 cell("Character messages", '<div class="pnl" style="gap: 6px;"><div class="srow"><span class="grow">Character</span>%s</div><p class="sub">Base persona</p><span class="sub" style="color: #15803D;">Saved.</span><span class="sub" style="color: #15803D;">Cleared: back to the base persona.</span><span class="sub" style="color: #B91C1C;">Couldn\'t reach the robot.</span><span class="sub" style="color: #B91C1C;">Couldn\'t save that.</span></div>' % sw(False, "Character")),
 cell("Copy logs, link to the robot app", '<div class="pnl" style="gap: 6px;"><span class="sub">Copied</span><span class="sub">Nothing to copy</span><span class="sub" style="color: #B91C1C;">Copy failed: select the log and press Ctrl+C.</span><span class="live" style="padding: 0; color: #8A3B00;"><span class="spin" style="width: 10px; height: 10px;"></span>Reconnecting: values may be out of date</span></div>'),
 cell("Transcript details", '<div class="pnl" style="gap: 8px;"><div class="bub person" style="max-width: 100%%;"><i class="muted">(no transcript)</i><div class="meta">Turn 3</div></div>%s</div>' % '<button class="cue" type="button" style="min-height: 0; background: #2A2521;"><span class="ch"><span class="k" style="background: #4A433C; color: #D8D1C7;">·</span><span class="lb">Cue without a hotkey</span></span></button>'),
 cell("Wizard of Oz: robot not ready", '<div class="dark pnl" style="gap: 8px; background: #171412;"><div class="pnlh"><span class="pill p-off" style="height: 24px;"><span class="dot"></span>Stopped</span><span class="spacer"></span><button class="btn btn-sm" type="button" style="background: #DC2626; color: #FFFFFF;">STOP</button></div><div style="opacity: .45; display: grid; grid-template-columns: 1fr 1fr; gap: 8px; pointer-events: none;">%s%s</div><p class="sub">Cues are off until the robot is ready. STOP always works.</p></div>' % (cue("1", "Hello", "2.1s", "Hi, I'm Reachy."), cue("2", "Nice to meet you", "1.8s", ""))),
 cell("Wizard of Oz: Now line", '<div class="dark pnl" style="gap: 6px; background: #171412;"><p style="margin: 0; color: #FF8A8A; font-weight: 600;">error: robot not connected</p><p style="margin: 0; color: #FF8A8A; font-weight: 600;">error: no audio for "Why it works": press Rebuild</p><p style="margin: 0; color: #EDE8E1; font-weight: 600;">Stopped</p><p style="margin: 0; color: #EDE8E1; font-weight: 600;">Nod <span class="sub">(motion only: no bar, no countdown)</span></p></div>'),
 cell("Wizard of Oz: rebuild", '<div class="dark pnl" style="gap: 6px; background: #171412;"><button class="btn btn-sm busy" type="button" disabled="{{yes}}" style="background: #2A2521; color: #EDE8E1;">rebuilding…</button><p style="margin: 0; color: #EDE8E1;">Rebuilt 3 lines</p><p style="margin: 0; color: #EDE8E1;">Everything is already up to date</p><p style="margin: 0; color: #FFC56B;">Rebuilt 2, 1 failed: see the log</p><p style="margin: 0; color: #A79F95;">Reload script: reloaded 23 cues</p></div>'),
 cell("New cue", '<div class="pnl" style="gap: 8px;"><h2 style="font-size: 16px; margin: 0;">New cue</h2><div class="field"><label>Name, on the card</label><input class="input" type="text" placeholder="Name"></div><div style="display: grid; grid-template-columns: 1fr 1fr; gap: 8px;"><div class="field"><label>Motion</label>%s</div><div class="field"><label>Which</label>%s</div></div><div style="display: flex; gap: 8px; justify-content: flex-end;"><button class="btn btn-dark busy" type="button" disabled="{{yes}}" style="min-height: 36px;">saving + re-recording…</button></div>%s</div>' % (sel(["none"], aria="Motion"), sel(["(none)"], aria="Which", style="opacity: .5;"), n("err", "alert", "Couldn't re-record the line: the voice service timed out. Nothing was saved."))),
 cell("Delete a cue", '<div class="pnl" style="gap: 8px;"><p style="margin: 0; font-weight: 600;">Delete "Why it works"? Its recording is deleted too.</p><div style="display: flex; gap: 8px;">%s%s</div>%s</div>' % (btn("Delete", "stop", "trash", extra=SM), btn("Cancel", "ghost", extra=SM), n("err", "alert", "That cue is playing right now. Stop it first."))),
 cell("Robot WiFi states", '<div class="pnl" style="gap: 6px;"><p class="note"><span class="spin" style="margin-top: 3px;"></span><span>Saving on the robot…</span></p><span class="sub" style="color: #8A3B00;">Type the hotspot\'s name first.</span><span class="sub" style="color: #B91C1C;">Couldn\'t ask the robot: timeout.</span><span class="sub" style="color: #B91C1C;">WiFi can only be set when the app runs on the robot.</span><span class="sub">Knows: nothing yet</span></div>'),
]
write("RAMoreTalk.dc.html", page("reachy_app: more Talk and Wizard of Oz states", grid(cells_k), "renderVals() { return { yes: true }; }", width=1600, height=1500, extra_css=RA_CSS + SHOW_CSS, mono=True))
